/* DATDEV MOBILE — zero-dependency UI prototype. Demo data only; no payment, account or fulfilment backend. */
(() => {
'use strict';
const $ = s => document.querySelector(s);
const E = s => String(s ?? '').replace(/[&<>"']/g, m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const money = n => new Intl.NumberFormat('vi-VN').format(Number(n||0))+'đ';
const asset = filename => './assets/'+filename;
const storage = {read(k,def){try{const v=localStorage.getItem('datdev_'+k);return v?JSON.parse(v):def}catch{return def}},write(k,v){try{localStorage.setItem('datdev_'+k,JSON.stringify(v))}catch{}}};
let products = [...initialProducts,...storage.read('newproducts',[])];
let cart=storage.read('cart',[]), wish=storage.read('wish',[]), compared=storage.read('compare',[]), orders=storage.read('orders',[]);
let voucher=storage.read('voucher','');
let brandFilter='Tất cả',sortFilter='featured',maxPrice=50000000;
let adminModal=false, selectedOrder=0;
let selectedSize='256GB', selectedColor=0;
const icons={search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',cart:'<circle cx="9" cy="20" r="1"/><circle cx="19" cy="20" r="1"/><path d="M2 3h2l3.2 12h12.3l2-9H5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 3.5-7 8-7s8 3 8 7"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1-1.1a5.5 5.5 0 0 0-7.8 7.8l8.8 8.6 8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',arrow:'<path d="M4 12h16m-7-7 7 7-7 7"/>',chevron:'<path d="m6 9 6 6 6-6"/>',check:'<path d="m4 12 5 5L20 6"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>',truck:'<path d="M2 5h12v12H2zM14 9h4l4 4v4h-8"/><circle cx="6" cy="19" r="2"/><circle cx="18" cy="19" r="2"/>',rotate:'<path d="M3 10a9 9 0 0 1 16-4l2 3M21 14a9 9 0 0 1-16 4l-2-3M21 3v6h-6M3 21v-6h6"/>',pin:'<path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',filter:'<path d="M3 5h18M6 12h12M10 19h4"/>',plus:'<path d="M12 4v16M4 12h16"/>',minus:'<path d="M4 12h16"/>',close:'<path d="M5 5l14 14M19 5 5 19"/>',star:'<path d="m12 2 3.1 6.3 7 1-5.1 5 1.2 7-6.2-3.3-6.2 3.3 1.2-7-5.1-5 7-1L12 2Z"/>',checkcircle:'<circle cx="12" cy="12" r="10"/><path d="m7 12 3 3 7-7"/>',headset:'<path d="M3 14v-3a9 9 0 0 1 18 0v3M4 14h3v6H4a2 2 0 0 1-2-2v-2a2 2 0 0 1 2-2Zm13 0h3a2 2 0 0 1 2 2v2a2 2 0 0 1-2 2h-3v-6Z"/>',package:'<path d="m12 2 9 5-9 5-9-5 9-5Zm-9 5v10l9 5 9-5V7M12 12v10"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',chart:'<path d="M3 3v18h18M6 16l5-6 4 3 6-8"/>',tag:'<path d="M20 12 12 20 3 11V3h8l9 9Z"/><circle cx="8" cy="8" r="1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6M12 7h.01"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 6 10 8L22 6"/>',phone:'<rect x="7" y="2" width="10" height="20" rx="2"/><path d="M11 18h2"/>',lock:'<rect x="5" y="10" width="14" height="12" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',trash:'<path d="M3 6h18M8 6V4h8v2M6 6l1 15h10l1-15M10 10v7M14 10v7"/>',edit:'<path d="M4 20h4L20 8l-4-4L4 16v4ZM14 6l4 4"/>',credit:'<rect x="2" y="5" width="20" height="14" rx="2"/><path d="M2 10h20"/>',logout:'<path d="M10 3H4v18h6M13 7l5 5-5 5M8 12h10"/>',store:'<path d="M3 9 5 3h14l2 6v3c-1 2-4 2-5 0-1 2-4 2-5 0-1 2-4 2-5 0-1 2-4 2-5 0V9ZM5 13v8h14v-8"/>',clock:'<circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/>'};
function icon(name,cls=''){return `<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.info}</svg>`}
const navLinks=[['#/dien-thoai','Điện thoại'],['#/phu-kien','Phụ kiện'],['#/uu-dai','Ưu đãi'],['#/thu-cu-doi-moi','Thu cũ đổi mới'],['#/tra-gop','Trả góp'],['#/cua-hang','Cửa hàng']];
function path(){return (location.hash.slice(1)||'/').split('?')[0]}
function params(){return new URLSearchParams((location.hash.split('?')[1]||''))}
function go(to){location.hash='#'+to;window.scrollTo({top:0,behavior:'instant'});render()}
function save(){storage.write('cart',cart);storage.write('wish',wish);storage.write('compare',compared);storage.write('orders',orders);storage.write('voucher',voucher)}
function notice(s){const el=$('#toast');el.textContent=s;el.classList.add('visible');clearTimeout(notice.t);notice.t=setTimeout(()=>el.classList.remove('visible'),2500)}
function header(){const active=path();return `<header class="site-header"><div class="container header-inner"><a href="#/" class="logo" aria-label="DatDev Mobile trang chủ"><strong>DatDev</strong><span class="slash">/</span><em>MOBILE</em></a><nav class="nav" aria-label="Điều hướng chính">${navLinks.map(([href,label])=>`<a href="${href}" class="${active===href.slice(1)?'active':''}">${label}</a>`).join('')}</nav><form id="searchForm" class="header-search" role="search">${icon('search')}<input name="q" aria-label="Tìm kiếm sản phẩm" placeholder="Tìm điện thoại, phụ kiện..." autocomplete="off"/><button class="sr-only">Tìm kiếm</button></form><div class="header-actions"><a class="icon-button" href="#/yeu-thich" aria-label="Sản phẩm yêu thích">${icon('heart')}${wish.length?`<span class="count">${wish.length}</span>`:''}</a><a class="icon-button" href="#/tai-khoan" aria-label="Tài khoản">${icon('user')}</a><a class="icon-button" href="#/gio-hang" aria-label="Giỏ hàng">${icon('cart')}<span class="count">${cart.reduce((sum,x)=>sum+x.qty,0)}</span></a><button class="icon-button mobile-menu" aria-label="Mở menu" data-action="menu">${icon('menu')}</button></div></div><nav class="mobile-nav" id="mobileNav">${[...navLinks,['#/so-sanh','So sánh'],['#/bao-hanh','Bảo hành'],['#/ho-tro','Hỗ trợ'],['#/cam-nang','Cẩm nang'],['#/admin','Admin demo']].map(([href,label])=>`<a href="${href}">${label}</a>`).join('')}</nav></header>`}
function footer(){return `<footer class="site-footer"><div class="container"><div class="footer-grid"><div><a href="#/" class="logo"><strong>DatDev</strong><span class="slash">/</span><em>MOBILE</em></a><p style="margin-top:17px;max-width:260px">Công nghệ đúng chất bạn. Giao diện thương mại điện tử được thiết kế từ một bản sắc duy nhất.</p><p><span class="chip dark">DEMO UI/UX</span></p></div><div><h4>Khám phá</h4><a href="#/dien-thoai">Điện thoại</a><a href="#/uu-dai">Ưu đãi</a><a href="#/so-sanh">So sánh sản phẩm</a><a href="#/cam-nang">Cẩm nang</a></div><div><h4>Dịch vụ</h4><a href="#/thu-cu-doi-moi">Thu cũ đổi mới</a><a href="#/tra-gop">Trả góp</a><a href="#/bao-hanh">Bảo hành</a><a href="#/cua-hang">Cửa hàng</a></div><div><h4>Khách hàng</h4><a href="#/tai-khoan">Tài khoản</a><a href="#/don-hang">Lịch sử đơn</a><a href="#/tra-cuu">Tra cứu đơn</a><a href="#/ho-tro">Trung tâm hỗ trợ</a></div><div><h4>Vận hành demo</h4><a href="#/admin">Admin Dashboard</a><a href="#/admin/san-pham">Sản phẩm / CRUD</a><a href="#/admin/kho">Kho hàng</a><a href="#/admin/don-hang">Quản lý đơn</a></div></div><div class="footer-bottom"><span>© 2026 DatDev Mobile — Bản mẫu thiết kế, không phải cửa hàng kinh doanh.</span><span>Giá, chính sách, số liệu và hình ảnh chỉ dùng minh họa.</span></div></div></footer>`}
const crumb=(name,parents=[])=>`<div class="breadcrumbs"><a href="#/">Trang chủ</a>${parents.map(x=>`<span>›</span><a href="${x[1]}">${E(x[0])}</a>`).join('')}<span>›</span><span>${E(name)}</span></div>`;
const benefits=()=>`<div class="benefits">${[['shield','Nguồn hàng rõ ràng','Xem chính sách trước khi mua'],['credit','Hỗ trợ trả góp','Tính số tiền dự kiến'],['truck','Giao hàng tiện lợi','Theo địa chỉ bạn chọn'],['headset','Tư vấn nhanh chóng','Kết nối với đội hỗ trợ']].map(([i,t,s])=>`<div class="benefit">${icon(i)}<div><strong>${t}</strong><span>${s}</span></div></div>`).join('')}</div>`;
const listingCard=p=>`<article class="product-card"><div class="product-media"><span class="chip dark">${E(p.badge)}</span><button class="heart ${wish.includes(p.id)?'is-active':''}" aria-label="${wish.includes(p.id)?'Bỏ yêu thích':'Yêu thích'} ${E(p.name)}" data-action="wish" data-id="${E(p.id)}">${icon('heart')}</button><a href="#/san-pham/${encodeURIComponent(p.id)}"><img loading="lazy" src="${asset(p.image)}" alt="${E(p.name)}"/></a></div><div class="product-body"><a href="#/san-pham/${encodeURIComponent(p.id)}"><h3>${E(p.name)} ${E(p.storage)}</h3></a><span class="rating"><b>★</b> ${p.rate} · ${new Intl.NumberFormat('vi-VN').format(p.reviews||0)} đánh giá minh họa</span><div class="price-line"><span class="price">${money(p.price)}</span><span class="discount">-${Math.round((1-p.price/p.oldPrice)*100)}%</span></div><div class="oldprice">${money(p.oldPrice)}</div><div class="installment-note">${icon('calendar')} Trả góp tham khảo từ ${money(Math.ceil(p.price/12))}/tháng</div><div class="card-actions"><button class="btn outline" data-action="compare" data-id="${E(p.id)}" title="So sánh">${icon('rotate')} So sánh</button><button class="btn" data-action="add" data-id="${E(p.id)}">${icon('cart')} Thêm vào giỏ</button></div></div></article>`;
const listingCards=(arr)=>arr.length?`<div class="card-grid">${arr.map(listingCard).join('')}</div>`:`<div class="empty">${icon('search')}<h3>Chưa tìm thấy sản phẩm phù hợp</h3><p class="muted mt8">Thử thay đổi bộ lọc hoặc từ khóa tìm kiếm.</p><a class="btn mt16" href="#/dien-thoai">Xem tất cả điện thoại ${icon('arrow')}</a></div>`;
function home(){const featured=products.slice(0,3);return `<section class="hero"><div class="container hero-content"><span class="eyebrow" style="color:var(--lime)">DATDEV MOBILE — CREATIVE TECH RETAIL</span><h1 style="margin-top:20px">Công nghệ.<br/><span>Đúng chất bạn.</span></h1><p class="lead">Từ chiếc điện thoại đầu tiên đến bản nâng cấp đáng mong chờ. Khám phá sản phẩm phù hợp với cách bạn sống.</p><div class="hero-actions"><a class="btn" href="#/dien-thoai">Khám phá ngay ${icon('arrow')}</a><a class="btn outline" style="border-color:#8f918b;color:white" href="#/so-sanh">So sánh sản phẩm ${icon('arrow')}</a></div></div><div class="hero-bottom"><b></b><b></b><b></b></div></section>
<div class="container"><section class="section"><div class="product-feature-grid"><div class="feature-copy"><span class="eyebrow">LỰA CHỌN NỔI BẬT</span><h2>Những thiết bị<br/>đáng trải nghiệm.</h2><p class="muted">Khám phá điện thoại với mức giá demo và bộ lọc thông minh.</p><a class="text-link mt16" href="#/dien-thoai">Xem toàn bộ sản phẩm ${icon('arrow')}</a></div>${featured.map(p=>`<a href="#/san-pham/${p.id}" class="feature-card"><span class="chip">${E(p.badge)}</span><h3>${E(p.name)}</h3><p>${E(p.desc)}</p><img src="${asset(p.image)}" alt="${E(p.name)}"/><strong>${money(p.price)}</strong></a>`).join('')}</div></section>
<section class="section-tight"><div class="section-head"><div><span class="eyebrow">KHÁM PHÁ THEO NHU CẦU</span><h2 style="margin-top:10px">Chọn đúng cho bạn.</h2></div></div><div class="category-grid">${[['Apple','phone-apple.webp'],['Samsung','phone-samsung.webp'],['Xiaomi','phone-xiaomi.webp'],['Nothing','phone-nothing.webp'],['Thu cũ đổi mới','phone-apple-pink.webp']].map(([b,i])=>`<a href="${b==='Thu cũ đổi mới'?'#/thu-cu-doi-moi':'#/dien-thoai?brand='+encodeURIComponent(b)}" class="category-tile"><img src="${asset(i)}" alt="${E(b)}"/><div><span>${E(b)}</span><div>${icon('arrow')}</div></div></a>`).join('')}</div>${benefits()}</section>
<section class="section"><div class="section-head"><div><span class="eyebrow">ĐƯỢC QUAN TÂM</span><h2 style="margin-top:10px">Mua theo cách của bạn.</h2></div><a class="text-link" href="#/dien-thoai">Tất cả sản phẩm ${icon('arrow')}</a></div>${listingCards(products.slice(0,4))}</section>
<section class="section-tight"><div class="wide-banner"><div><span class="eyebrow highlight">NÂNG CẤP THÔNG MINH</span><h2>Đổi máy cũ.<br/><span class="highlight">Mở trải nghiệm mới.</span></h2><p class="muted" style="color:#d2d2cf;margin-bottom:22px">Thử định giá thiết bị cũ trực tiếp trên website.</p><a class="btn" href="#/thu-cu-doi-moi">Thử định giá ${icon('arrow')}</a></div><img src="${asset('hero-tradein.webp')}" alt="Hình ảnh điện thoại thu cũ đổi mới"/></div></section>
<section class="section"><div class="section-head"><div><span class="eyebrow">EDITORIAL / TECH JOURNAL</span><h2 style="margin-top:10px">Công nghệ qua góc nhìn mới.</h2></div><a href="#/cam-nang" class="text-link">Đọc cẩm nang ${icon('arrow')}</a></div>${articlesCards(posts)}</section></div>`}
function listPage(isAccessory=false){let ps=[...products];let p=params();const chosenBrand=p.get('brand');if(chosenBrand && ['Apple','Samsung','Xiaomi','Nothing'].includes(chosenBrand))brandFilter=chosenBrand;if(brandFilter!=='Tất cả')ps=ps.filter(x=>x.brand===brandFilter);ps=ps.filter(x=>x.price<=maxPrice);if(sortFilter==='cheap')ps.sort((a,b)=>a.price-b.price);if(sortFilter==='expensive')ps.sort((a,b)=>b.price-a.price);if(sortFilter==='rating')ps.sort((a,b)=>b.rate-a.rate);
return `<div class="container">${crumb(isAccessory?'Phụ kiện':'Điện thoại')}<div class="page-hero"><div style="position:relative;z-index:1"><span class="eyebrow">${isAccessory?'ACCESSORIES':'SMARTPHONE COLLECTION'}</span><h1 style="margin-top:11px">${isAccessory?'Phụ kiện.':'Điện thoại.'}<br/><span style="font-weight:400">Chọn đúng chất riêng.</span></h1></div><img src="${asset('hero.webp')}" alt="Ảnh máy điện thoại"/></div>${isAccessory?`<div class="empty"><h3>Phụ kiện — bản xem trước UI</h3><p class="muted mt8">Danh mục phụ kiện sẽ sử dụng cùng hệ thống card, filter và chi tiết sản phẩm. Hiện dữ liệu mẫu tập trung vào điện thoại.</p><a href="#/dien-thoai" class="btn mt16">Khám phá điện thoại ${icon('arrow')}</a></div>`:`<div class="listing-layout"><aside class="filters"><h3>${icon('filter')} Bộ lọc nâng cao</h3><div class="filter-group"><strong>Thương hiệu</strong>${['Tất cả','Apple','Samsung','Xiaomi','Nothing'].map(b=>`<label><input type="radio" name="brand" value="${b}" ${brandFilter===b?'checked':''}/> ${b}</label>`).join('')}</div><div class="filter-group"><strong>Giá tối đa: <span id="rangeLabel">${money(maxPrice)}</span></strong><input id="maxPrice" type="range" min="9000000" max="50000000" step="1000000" value="${maxPrice}"/></div><div class="filter-group"><strong>Dung lượng phổ biến</strong><label><input type="checkbox" checked disabled/> 128GB – 512GB</label></div><div class="filter-group"><strong>Gợi ý nhanh</strong><p class="small" style="color:#bebfb9">Lọc theo hãng, ngân sách và sắp xếp để chọn máy phù hợp.</p></div><button class="btn outline full" data-action="resetFilters" style="color:white;border-color:#777">Xóa bộ lọc</button></aside><div><div class="toolbar"><div><h3>${ps.length} sản phẩm</h3><span class="muted small">Thông tin và giá trong bản demo</span></div><div class="group"><label class="small" for="sortProducts">Sắp xếp:</label><select id="sortProducts" style="min-width:175px"><option value="featured" ${sortFilter==='featured'?'selected':''}>Nổi bật</option><option value="cheap" ${sortFilter==='cheap'?'selected':''}>Giá thấp đến cao</option><option value="expensive" ${sortFilter==='expensive'?'selected':''}>Giá cao đến thấp</option><option value="rating" ${sortFilter==='rating'?'selected':''}>Đánh giá cao</option></select></div></div>${listingCards(ps)}</div></div>`}</div>`}
function searchPage(){const q=params().get('q')||'';const matches=products.filter(p=>(p.name+' '+p.brand+' '+p.desc).toLowerCase().includes(q.toLowerCase()));return `<div class="container">${crumb('Tìm kiếm')}<div class="page-hero"><div><span class="eyebrow">SEARCH RESULTS</span><h1 style="margin-top:10px">Kết quả tìm kiếm.</h1><p>Tìm thấy ${matches.length} sản phẩm cho “${E(q)}”.</p></div></div><div style="margin:25px 0">${listingCards(matches)}</div></div>`}
function productPage(id){const p=products.find(x=>x.id===id);if(!p)return notFound();if(!['128GB','256GB','512GB','1TB'].includes(selectedSize))selectedSize=p.storage;return `<div class="container">${crumb(p.name,[['Điện thoại','#/dien-thoai']])}<div class="product-detail-grid"><div><div class="detail-gallery"><img src="${asset(p.id==='iphone-16-pro'?'detail.webp':p.image)}" alt="Hình ảnh ${E(p.name)}"/></div><div class="flex wrap mt16">${[p.image,p.image,p.image].map((img,i)=>`<div class="panel" style="width:85px;height:80px;padding:10px"><img src="${asset(img)}" style="object-fit:contain;width:100%;height:100%" alt="Góc nhìn ${i+1}"/></div>`).join('')}</div></div><div class="detail-options"><span class="chip">${E(p.badge)}</span><h1>${E(p.name)}</h1><p>${E(p.desc)}</p><div class="mt16"> <span class="rating"><b>★</b> ${p.rate} · ${p.reviews} đánh giá mẫu</span></div><hr style="border:0;border-top:1px solid #ddd;margin:23px 0"/><strong>Màu sắc: ${E(p.color)}</strong><div class="swatches">${['#c6bdad','#3e444a','#edece6','#747a98'].map((c,i)=>`<button class="swatch ${selectedColor===i?'selected':''}" style="background:${c}" data-action="color" data-index="${i}" aria-label="Màu ${i+1}"></button>`).join('')}</div><div class="mt24"><strong>Dung lượng</strong><div>${['128GB','256GB','512GB','1TB'].map(s=>`<button class="option-btn ${selectedSize===s?'active':''}" data-action="size" data-value="${s}">${s}</button>`).join('')}</div></div><div class="panel-soft p24 mt24"><div class="flex">${icon('rotate')}<div><strong>Thu cũ đổi mới</strong><p class="small">Thử tính giá thu lại để nâng cấp</p></div></div><a href="#/thu-cu-doi-moi" class="text-link mt16">Tính giá máy cũ ${icon('arrow')}</a></div><div class="panel-soft p24 mt16"><div class="flex">${icon('credit')}<div><strong>Hỗ trợ trả góp</strong><p class="small">Chọn mức trả trước và kỳ hạn</p></div></div><a href="#/tra-gop" class="text-link mt16">Tính trả góp ${icon('arrow')}</a></div></div><aside class="buy-box"><span class="eyebrow">GIÁ BÁN DEMO</span><div class="price mt8">${money(p.price)}</div><div class="oldprice">${money(p.oldPrice)}</div><div class="mt16"><span class="chip green">${p.stock>0?'Còn hàng':'Hết hàng'}</span><span class="muted small"> &nbsp;Tồn minh họa: ${p.stock}</span></div><div class="panel-soft p24 mt16"><div class="flex">${icon('calendar')}<span class="small">Trả góp tham khảo từ <strong>${money(Math.ceil(p.price/12))}/tháng</strong></span></div></div><button class="btn full" data-action="add" data-id="${E(p.id)}">${icon('cart')} Thêm vào giỏ hàng</button><button class="btn dark full" data-action="buy" data-id="${E(p.id)}">Mua ngay ${icon('arrow')}</button><a href="#/cua-hang" class="btn outline full mt16">${icon('pin')} Xem điểm nhận hàng</a><p class="small muted mt16">Lưu ý: Giá và chính sách tại đây chỉ là dữ liệu mô phỏng, không có giao dịch thật.</p></aside></div><div class="detail-advantages">${[['shield','Kiểm tra nguồn gốc'],['rotate','Thông tin đổi trả'],['truck','Giao hàng theo địa chỉ'],['headset','Hỗ trợ trước & sau mua']].map(([i,t])=>`<div class="advantage">${icon(i)}<b>${t}</b></div>`).join('')}</div><section class="section"><div class="split"><div class="panel p32"><h3>Thông số kỹ thuật</h3><div class="mt24">${Object.entries(p.specs||{}).map(([k,v])=>`<div class="spec-row"><strong>${E(k)}</strong><span>${E(v)}</span></div>`).join('')}</div></div><div class="panel p32"><span class="eyebrow">PRODUCT STORY</span><h2 style="margin:14px 0">Một lựa chọn.<br/>Nhiều khả năng.</h2><p class="lead">${E(p.desc)} Hãy cân nhắc nhu cầu sử dụng, hiệu năng, màn hình và ngân sách để tìm đúng thiết bị dành cho bạn.</p><a href="#/so-sanh" class="btn mt24">So sánh với máy khác ${icon('arrow')}</a></div></div></section><section class="section-tight"><div class="section-head"><h2>Có thể bạn cũng thích.</h2></div>${listingCards(products.filter(x=>x.id!==p.id).slice(0,4))}</section></div>`}
function comparePage(){let p=compared.map(id=>products.find(x=>x.id===id)).filter(Boolean);if(!p.length)p=products.slice(0,3);const keys=['Màn hình','Chip','Camera','Pin','Kết nối','Chống nước'];return `<div class="container">${crumb('So sánh điện thoại')}<div class="page-hero"><div><span class="eyebrow">COMPARE TOOL</span><h1>So sánh để<br/>chọn đúng.</h1><p>Chọn tối đa 3 thiết bị để xem thông số và giá tham khảo.</p></div></div><div class="compare-wrap"><div class="compare-grid"><div class="heading"><h3>Thiết bị</h3><p class="small muted">${p.length} sản phẩm</p></div>${[0,1,2].map(i=>`<div class="heading"><select class="compare-select" data-index="${i}"><option value="">+ Chọn điện thoại</option>${products.map(pr=>`<option value="${pr.id}" ${p[i]?.id===pr.id?'selected':''}>${E(pr.name)}</option>`).join('')}</select>${p[i]?`<a href="#/san-pham/${p[i].id}"><img src="${asset(p[i].image)}" alt="${E(p[i].name)}"/></a><h3 style="font-size:18px">${E(p[i].name)}</h3><p class="price">${money(p[i].price)}</p><button class="btn small mt8" data-action="add" data-id="${p[i].id}">Thêm vào giỏ ${icon('arrow')}</button>`:'<p class="muted mt16">Chưa chọn sản phẩm</p>'}</div>`).join('')}${keys.map(k=>`<div class="label">${k}</div>${[0,1,2].map(i=>`<div class="${i===0?'good':''}">${p[i]?E(p[i].specs[k]||'—'):'—'}</div>`).join('')}`).join('')}</div></div><p class="small muted mt24">Thông số trong bản mẫu chỉ mang tính minh họa; cần thay bằng dữ liệu kỹ thuật đã xác minh trước khi bán.</p></div>`}
function offersPage(){return `<div class="container">${crumb('Ưu đãi')}<div class="promo-hero"><div><span class="eyebrow">SPECIAL DROPS</span><h1>DEAL ĐỈNH.<br/>GIÁ CHẤT.</h1><p style="max-width:360px;margin-top:11px">Ưu đãi mô phỏng dành riêng cho bản thiết kế DatDev Mobile.</p><a class="btn dark" href="#/dien-thoai">Săn ưu đãi ngay ${icon('arrow')}</a></div><img src="${asset('hero-offers.webp')}" alt="Hình ảnh điện thoại cao cấp"/></div><section class="section"><div class="section-head"><div><span class="eyebrow">PROMOTION EDIT</span><h2 style="margin-top:10px">Ưu đãi nổi bật.</h2></div></div>${listingCards([...products].sort((a,b)=>(b.oldPrice-b.price)-(a.oldPrice-a.price)).slice(0,8))}</section></div>`}
function tradeInPage(){return `<div class="container">${crumb('Thu cũ đổi mới')}<div class="page-hero dark" style="min-height:300px"><div style="position:relative;z-index:1"><span class="eyebrow highlight">TRADE IN / TRADE UP</span><h1 style="margin-top:13px">Đổi máy cũ.<br/><span class="highlight">Lên đời chất.</span></h1><p style="color:#ddd">Ước tính giá thu cũ, sau đó chọn điện thoại mới.</p></div><img src="${asset('hero-tradein.webp')}" alt="Thu cũ đổi mới"/></div><div class="steps"><span class="step active"><b>1</b> Chọn máy cũ</span><span class="step-line"></span><span class="step"><b>2</b> Định giá</span><span class="step-line"></span><span class="step"><b>3</b> Đổi máy</span></div><div class="split"><div class="panel p32"><h3>1. Thông tin máy hiện tại</h3><div class="form-row mt24"><div><label class="form-label">Hãng</label><select id="tradeBrand"><option>Apple</option><option>Samsung</option><option>Xiaomi</option><option>Nothing</option></select></div><div><label class="form-label">Model</label><select id="tradeModel"><option>iPhone 14 Pro Max</option><option>iPhone 15</option><option>Galaxy S23 Ultra</option><option>Xiaomi 13</option></select></div></div><div class="form-row"><div><label class="form-label">Dung lượng</label><select id="tradeStorage"><option>128GB</option><option selected>256GB</option><option>512GB</option></select></div><div><label class="form-label">Tình trạng</label><select id="tradeCondition"><option value="good">Tốt — ít trầy xước</option><option value="okay">Khá — trầy xước nhẹ</option><option value="bad">Trung bình — dấu hao mòn</option></select></div></div><p class="small muted mt16">Định giá này là công cụ mô phỏng giao diện, không phải báo giá thu mua thực tế.</p><button class="btn mt24" data-action="estimateTrade">Nhận giá ước tính ${icon('arrow')}</button></div><div class="panel p32"><span class="eyebrow">ƯỚC TÍNH ĐỔI MÁY</span><div id="tradeResult" class="range-result mt16"><p>Giá thu cũ giả định</p><strong>—</strong><p class="small">Chọn thông tin máy và nhấn “Nhận giá ước tính”.</p></div><div class="mt24"><h3>Quy trình 4 bước</h3>${[['01','Chọn thiết bị'],['02','Nhận giá dự kiến'],['03','Kiểm tra tại cửa hàng'],['04','Thanh toán chênh lệch']].map(([a,b])=>`<div class="money-row"><b>${a}</b><span>${b}</span></div>`).join('')}</div><a class="btn dark full mt24" href="#/dien-thoai">Chọn máy muốn nâng cấp ${icon('arrow')}</a></div></div></div>`}
function installmentPage(){const p=products[0];return `<div class="container">${crumb('Trả góp')}<div class="page-hero dark" style="min-height:280px"><div style="position:relative;z-index:1"><span class="eyebrow highlight">FINANCE YOUR TECH</span><h1 style="margin-top:12px">Sở hữu trước.<br/><span class="highlight">Thanh toán sau.</span></h1><p style="color:#d0d0cb">Thử tính khoản thanh toán hàng tháng theo tình huống giả định.</p></div><img src="${asset('hero-installment.webp')}" alt="Trải nghiệm trả góp điện thoại"/></div><div class="split section-tight"><div class="panel p32"><h3>Tính khoản trả góp của bạn</h3><div class="form-group mt24"><label class="form-label">Sản phẩm</label><select id="installProduct">${products.map(x=>`<option value="${x.id}">${E(x.name)} — ${money(x.price)}</option>`).join('')}</select></div><div class="form-group"><label class="form-label">Số tiền trả trước: <span id="depositLabel">${money(10000000)}</span></label><input id="depositInput" type="range" min="0" max="${p.price}" step="1000000" value="10000000" style="accent-color:#b4db36;width:100%"/></div><div class="form-group"><label class="form-label">Kỳ hạn (tháng)</label><select id="installMonths"><option value="3">3 tháng</option><option value="6" selected>6 tháng</option><option value="9">9 tháng</option><option value="12">12 tháng</option></select></div></div><div class="panel p32"><span class="eyebrow">KẾT QUẢ THAM KHẢO</span><div class="range-result mt16"><p>Số tiền dự kiến mỗi tháng</p><strong id="installMonthly">${money(Math.ceil((p.price-10000000)/6))}</strong><span> / tháng</span><div id="installMeta" class="money-row"><span>Tạm tính theo lãi suất</span><b>0% (giả định)</b></div></div><p class="small muted mt16">Phép tính chia đều phần tiền còn lại, chưa tính phí dịch vụ, bảo hiểm, điều kiện duyệt hay lãi suất thực tế. Không phải cam kết 0%.</p><a href="#/ho-tro" class="btn dark full mt24">Liên hệ tư vấn ${icon('arrow')}</a></div></div></div>`}
const summaryTotals=()=>{const items=cart.map(x=>({item:x,p:products.find(p=>p.id===x.id)})).filter(x=>x.p);const sub=items.reduce((sum,x)=>sum+x.p.price*x.item.qty,0);const discount=voucher.trim().toUpperCase()==='DATDEV100'?Math.min(100000,sub):0;return {sub,discount,total:sub-discount,items}};
function cartPage(){const {sub,discount,total,items}=summaryTotals();return `<div class="container">${crumb('Giỏ hàng')}<div class="section-head"><div><span class="eyebrow">YOUR BASKET</span><h1 style="font-size:47px;margin:10px 0 5px">Giỏ hàng của bạn.</h1><p>${items.reduce((s,x)=>s+x.item.qty,0)} sản phẩm đang trong giỏ.</p></div></div>${items.length?`<div class="basket-layout"><div class="panel">${items.map(({p,item})=>`<div class="cart-row"><a href="#/san-pham/${p.id}"><img src="${asset(p.image)}" alt="${E(p.name)}"/></a><div><a href="#/san-pham/${p.id}"><h3>${E(p.name)}</h3></a><p class="small muted">${E(item.size||p.storage)} · ${E(p.color)}</p><div class="flex mt16"><span class="chip green">Còn hàng</span><span class="small muted">Bảo hành demo</span></div></div><div style="text-align:right"><strong class="price">${money(p.price*item.qty)}</strong><div class="cart-qty mt16" style="margin-left:auto"><button data-action="qty" data-id="${p.id}" data-amount="-1" aria-label="Giảm số lượng">${icon('minus')}</button><b>${item.qty}</b><button data-action="qty" data-id="${p.id}" data-amount="1" aria-label="Tăng số lượng">${icon('plus')}</button></div><button class="icon-button mt16" data-action="remove" data-id="${p.id}" aria-label="Xóa sản phẩm" style="color:#333">${icon('trash')}</button></div></div>`).join('')}<div class="p24 flex between"><a class="btn outline small" href="#/dien-thoai">${icon('arrow')} Tiếp tục mua sắm</a><button class="btn outline small" data-action="clearCart">Xóa tất cả</button></div></div><aside class="panel summary"><h3>Tóm tắt đơn hàng</h3><div class="money-row"><span>Tạm tính</span><b>${money(sub)}</b></div><div class="money-row"><span>Giảm voucher</span><b style="color:#5a8d00">-${money(discount)}</b></div><div class="money-row"><span>Giao hàng</span><b>Chưa tính</b></div><label class="form-label mt16">Mã ưu đãi (demo: DATDEV100)</label><div class="flex"><input class="field" id="voucherInput" value="${E(voucher)}" placeholder="Nhập mã ưu đãi"/><button class="btn outline" data-action="voucher">Áp dụng</button></div><div class="money-row total"><span>Tổng</span><b>${money(total)}</b></div><a class="btn full" href="#/thanh-toan">Tiếp tục thanh toán ${icon('arrow')}</a><p class="small muted mt16">Đây là hành trình giả lập, không thể thu tiền thật.</p></aside></div>`:`<div class="empty">${icon('cart')}<h3>Giỏ hàng đang trống</h3><p class="muted mt8">Chọn thiết bị bạn yêu thích để bắt đầu trải nghiệm.</p><a href="#/dien-thoai" class="btn mt16">Khám phá điện thoại ${icon('arrow')}</a></div>`}</div>`}
function checkoutPage(){const t=summaryTotals();if(!t.items.length)return `<div class="container">${crumb('Thanh toán')}<div class="empty"><h3>Chưa có sản phẩm để thanh toán</h3><a href="#/dien-thoai" class="btn mt16">Mua sắm ngay</a></div></div>`;return `<div class="container">${crumb('Thanh toán')}<div class="section-head"><div><span class="eyebrow">CHECKOUT / DEMO</span><h1 style="font-size:42px;margin-top:8px">Hoàn tất đơn hàng.</h1><p>Không cần tạo tài khoản để thử đặt hàng.</p></div></div><div class="steps"><span class="step active"><b>${icon('check')}</b> Giỏ hàng</span><span class="step-line"></span><span class="step active"><b>2</b> Thông tin</span><span class="step-line"></span><span class="step"><b>3</b> Hoàn tất</span></div><form id="checkoutForm" class="form-columns"><div class="panel"><section class="form-section"><h3>01. Thông tin người nhận</h3><div class="form-row mt24"><div><label class="form-label" for="buyerName">Họ và tên *</label><input class="field" name="buyerName" id="buyerName" required minlength="2" placeholder="Nguyễn Văn A" autocomplete="name"/></div><div><label class="form-label" for="buyerPhone">Số điện thoại *</label><input class="field" name="buyerPhone" id="buyerPhone" required pattern="[0-9+ ]{9,15}" placeholder="09xx xxx xxx" autocomplete="tel"/></div></div><div><label class="form-label" for="buyerEmail">Email (không bắt buộc)</label><input class="field" type="email" name="buyerEmail" id="buyerEmail" placeholder="ban@example.com" autocomplete="email"/></div></section><section class="form-section"><h3>02. Nhận hàng</h3><div class="choice-grid mt16"><label class="choice"><input type="radio" name="delivery" value="Giao tận nơi" checked/> ${icon('truck')} Giao tận nơi</label><label class="choice"><input type="radio" name="delivery" value="Nhận tại cửa hàng"/> ${icon('store')} Nhận tại cửa hàng</label></div><div class="form-group mt16"><label class="form-label">Địa chỉ nhận hàng *</label><input class="field" name="address" required placeholder="Số nhà, tên đường, phường/xã, tỉnh/thành"/></div></section><section class="form-section"><h3>03. Phương thức thanh toán</h3><div class="choice-grid mt16"><label class="choice"><input type="radio" name="payment" value="COD" checked/> ${icon('package')} Thanh toán khi nhận hàng</label><label class="choice"><input type="radio" name="payment" value="Chuyển khoản demo"/> ${icon('credit')} Chuyển khoản (mô phỏng)</label></div><p class="small muted mt16">Không tích hợp cổng thanh toán, không yêu cầu nhập thông tin thẻ.</p><div class="form-group mt16"><label class="form-label">Ghi chú đơn hàng</label><textarea class="field" name="note" rows="3" placeholder="Lưu ý khi giao hàng..."></textarea></div><label class="choice" style="border:0;padding:0"><input type="checkbox" required/> Tôi hiểu đây là đơn hàng mô phỏng và không có giao dịch thật.</label></section></div><aside class="panel summary"><h3>Đơn hàng (${t.items.length} loại)</h3>${t.items.map(({p,item})=>`<div class="money-row"><span>${E(p.name)} × ${item.qty}</span><b>${money(p.price*item.qty)}</b></div>`).join('')}<div class="money-row"><span>Giảm giá</span><b>-${money(t.discount)}</b></div><div class="money-row"><span>Giao hàng</span><b>Dữ liệu demo</b></div><div class="money-row total"><span>Tổng thanh toán</span><b>${money(t.total)}</b></div><button class="btn full" type="submit">Đặt hàng demo ${icon('arrow')}</button><p class="small muted mt16">Không có thanh toán hay giao nhận thực tế.</p></aside></form></div>`}
function successPage(){const o=orders[0];if(!o)return `<div class="container"><div class="empty"><h3>Chưa có đơn hàng demo</h3><a class="btn mt16" href="#/dien-thoai">Khám phá sản phẩm</a></div></div>`;return `<div class="container"><div class="page-hero dark" style="min-height:275px;margin-top:22px"><div style="z-index:2"><span class="chip">ĐƠN HÀNG ĐÃ GHI NHẬN (DEMO)</span><h1 style="margin-top:15px">Đặt hàng<br/><span class="highlight">thành công!</span></h1><p style="color:#ddd">Cảm ơn bạn đã trải nghiệm bản mẫu DatDev Mobile.</p><div class="chip dark mt16">Mã đơn: ${E(o.id)}</div></div><img src="${asset('hero.webp')}" alt="Điện thoại"/></div><div class="split mt24"><div class="panel p32"><h3>Chi tiết đơn hàng</h3>${o.items.map(item=>`<div class="money-row"><span>${E(item.name)} × ${item.qty}</span><b>${money(item.price*item.qty)}</b></div>`).join('')}<div class="money-row"><b>Tổng</b><b>${money(o.total)}</b></div><p class="mt16"><b>Người nhận:</b> ${E(o.name)} · ${E(o.phone)}</p><p><b>Địa chỉ:</b> ${E(o.address)}</p><p><b>Phương thức:</b> ${E(o.payment)}</p></div><div class="panel p32"><h3>Trạng thái đơn</h3>${statusTimeline(o.status)}<p class="small muted mt16">Trạng thái do hệ thống demo tự lưu. Không kết nối đơn vị giao hàng.</p><a href="#/tra-cuu?id=${encodeURIComponent(o.id)}" class="btn dark full mt24">Tra cứu đơn ${icon('arrow')}</a><a href="#/dien-thoai" class="btn full mt16">Tiếp tục mua sắm</a></div></div></div>`}
const stages=['Đã xác nhận','Đang chuẩn bị','Đang giao','Đã giao'];
function statusTimeline(status){let index=Math.max(0,stages.indexOf(status));return `<div class="status-line">${stages.map((s,i)=>`<div class="status-item ${i<=index?'done':''}"><div class="circle">${i<=index?icon('check'):i+1}</div><b>${s}</b></div>`).join('')}</div>`}
function trackPage(){const requested=params().get('id')||'';const found=orders.find(x=>x.id===requested)||(orders.length===1?orders[0]:null);return `<div class="container">${crumb('Tra cứu đơn hàng')}<div class="page-hero dark" style="min-height:260px"><div style="z-index:1"><span class="eyebrow highlight">TRACK YOUR ORDER</span><h1 style="margin:12px 0">Tra cứu đơn hàng.</h1><p style="color:#ddd">Xem trạng thái của các đơn được tạo trong trình duyệt này.</p></div><img src="${asset('hero.webp')}" alt="Điện thoại"/></div><form id="trackForm" class="panel p24 mt24" style="display:flex;gap:12px"><input class="field" name="orderId" value="${E(requested)}" required placeholder="Mã đơn: DDM-..."/><button class="btn" type="submit">Kiểm tra ${icon('arrow')}</button></form>${found?`<div class="panel p32 mt24"><div class="flex between"><div><span class="eyebrow">MÃ ĐƠN HÀNG</span><h3>${E(found.id)}</h3></div><span class="chip green">${E(found.status)}</span></div>${statusTimeline(found.status)}<div class="money-row mt24"><span>Người nhận</span><b>${E(found.name)}</b></div><div class="money-row"><span>Ngày đặt</span><b>${E(found.date)}</b></div><div class="money-row"><span>Tổng tiền</span><b>${money(found.total)}</b></div></div>`:`<div class="empty mt24">${icon('package')}<h3>${requested?'Không tìm thấy đơn hàng trong bản demo':'Nhập mã đơn hàng để tra cứu'}</h3><p class="muted mt8">Dữ liệu đơn hàng được lưu cục bộ trong trình duyệt tạo đơn.</p></div>`}</div>`}
function loginPage(){return `<div style="display:grid;grid-template-columns:1fr 1fr;min-height:calc(100vh - 76px)"><div style="background:#151515 url('${asset('hero-login.webp')}') center/cover;color:#fff;padding:54px;display:flex;flex-direction:column;justify-content:flex-start"><span class="eyebrow highlight">DATDEV MEMBER</span><h1 style="margin-top:40px;font-size:clamp(36px,4.5vw,68px)">Mọi trải nghiệm<br/><span class="highlight">bắt đầu từ đây.</span></h1><p style="max-width:330px;margin-top:20px">Khám phá và lưu lại những món công nghệ hợp gu.</p></div><div style="padding:min(6vw,85px);display:flex;flex-direction:column;justify-content:center"><span class="eyebrow">DEMO LOGIN</span><h2 class="mt16">Đăng nhập DatDev.</h2><p class="muted mt8">Trang minh họa giao diện xác thực. Không gửi SMS hay email thật.</p><form id="loginForm" class="mt24"><label class="form-label">Số điện thoại hoặc email</label><input class="field" type="text" name="identity" required placeholder="Nhập email hoặc số điện thoại"/><label class="form-label mt16">Mã OTP demo (123456)</label><input class="field" name="otp" pattern="123456" required placeholder="Nhập 123456"/><button class="btn full mt24">Tiếp tục ${icon('arrow')}</button></form><p class="small muted mt24">Để mua hàng thật, cần triển khai xác thực bảo mật ở backend, không dùng mã OTP cố định.</p><a href="#/thanh-toan" class="text-link mt24">Tiếp tục mua sắm không cần tài khoản ${icon('arrow')}</a></div></div>`}
function wishlistPage(){const ps=wish.map(id=>products.find(p=>p.id===id)).filter(Boolean);return `<div class="container">${crumb('Yêu thích')}<div class="page-hero"><div><span class="eyebrow">YOUR FAVORITES</span><h1 style="margin-top:10px">Sản phẩm yêu thích.</h1><p>Bạn đã lưu ${ps.length} sản phẩm.</p></div><img src="${asset('hero.webp')}" alt="Điện thoại"/></div><div class="section-tight">${listingCards(ps)}</div></div>`}
function accountMenu(active){const links=[['#/tai-khoan','Tổng quan','grid'],['#/don-hang','Đơn hàng của tôi','package'],['#/yeu-thich','Yêu thích','heart'],['#/tra-cuu','Tra cứu đơn','truck'],['#/bao-hanh','Bảo hành','shield'],['#/dang-nhap','Đăng nhập demo','user']];return `<aside class="panel account-menu">${links.map(([href,label,i])=>`<a href="${href}" class="${active===href.slice(1)?'active':''}">${icon(i)}${label}</a>`).join('')}</aside>`}
function accountPage(){const login=storage.read('login',null);return `<div class="container">${crumb('Tài khoản')}<div class="account-layout"><div>${accountMenu('/tai-khoan')}</div><div><h2>Chào mừng${login?', '+E(login):''}.</h2><p class="muted mt8">Tổng quan trải nghiệm mua sắm tại DatDev Mobile.</p><div class="kpis"><div class="kpi">${icon('package')}<strong>${orders.length}</strong><span>Đơn hàng demo</span></div><div class="kpi">${icon('truck')}<strong>${orders.filter(x=>x.status==='Đang giao').length}</strong><span>Đang giao (demo)</span></div><div class="kpi">${icon('heart')}<strong>${wish.length}</strong><span>Đã yêu thích</span></div><div class="kpi">${icon('credit')}<strong>${money(orders.reduce((s,o)=>s+o.total,0))}</strong><span>Tổng đơn đã tạo</span></div></div><div class="panel p32"><div class="section-head"><h3>Đơn hàng gần đây</h3><a href="#/don-hang" class="text-link">Xem tất cả ${icon('arrow')}</a></div>${orderList(orders.slice(0,3))}</div><div class="wide-banner mt24" style="min-height:230px"><div><span class="eyebrow highlight">YOUR NEXT DEVICE</span><h2 style="font-size:32px">Tìm chiếc máy tiếp theo.</h2><a class="btn" href="#/dien-thoai">Khám phá ${icon('arrow')}</a></div><img src="${asset('hero.webp')}" alt="Điện thoại"/></div></div></div></div>`}
function orderList(list){return list.length?list.map(o=>`<article style="padding:16px 0;border-bottom:1px solid var(--line)"><div class="flex between wrap"><div><b>${E(o.id)}</b><p class="small muted">${E(o.date)} · ${o.items.length} loại sản phẩm</p></div><span class="chip ${o.status==='Đã giao'?'green':'ghost'}">${E(o.status)}</span></div><div class="flex between mt16 wrap"><strong>${money(o.total)}</strong><div class="flex"><a class="btn small outline" href="#/tra-cuu?id=${encodeURIComponent(o.id)}">Theo dõi</a><button class="btn small" data-action="reorder" data-id="${E(o.id)}">Mua lại ${icon('arrow')}</button></div></div></article>`).join(''):`<p class="muted mt16">Chưa có đơn hàng nào. <a class="text-link" href="#/dien-thoai">Bắt đầu mua sắm ${icon('arrow')}</a></p>`}
function ordersPage(){return `<div class="container">${crumb('Lịch sử đơn hàng')}<div class="account-layout"><div>${accountMenu('/don-hang')}</div><div><div class="page-hero dark"><div style="z-index:1"><span class="eyebrow highlight">ORDER HISTORY</span><h1 style="margin-top:10px">Lịch sử<br/>đơn hàng.</h1></div><img src="${asset('hero.webp')}" alt="Điện thoại"/></div><div class="kpis"><div class="kpi"><span>Tổng đơn</span><strong>${orders.length}</strong></div><div class="kpi"><span>Đã giao</span><strong>${orders.filter(x=>x.status==='Đã giao').length}</strong></div><div class="kpi"><span>Đang xử lý</span><strong>${orders.filter(x=>x.status!=='Đã giao').length}</strong></div><div class="kpi"><span>Tổng giá trị</span><strong style="font-size:22px">${money(orders.reduce((s,o)=>s+o.total,0))}</strong></div></div><div class="panel p32"><h3>Đơn hàng của bạn</h3>${orderList(orders)}</div></div></div></div>`}
function warrantyPage(){return `<div class="container">${crumb('Bảo hành')}<div class="page-hero dark" style="min-height:270px"><div style="z-index:1"><span class="eyebrow highlight">AFTER SALES CARE</span><h1 class="mt16">An tâm sau<br/><span class="highlight">mỗi lần mua.</span></h1><p style="color:#ddd">Tra cứu thông tin và đăng ký yêu cầu dịch vụ.</p></div><img src="${asset('hero-warranty.webp')}" alt="Điện thoại bảo hành"/></div><div class="panel p32 mt24"><div class="split"><div><span class="eyebrow">TRA CỨU BẢO HÀNH</span><h3 class="mt8">Kiểm tra thời hạn của thiết bị.</h3><p class="small muted mt8">Bản demo nhận mã đơn đã tạo trong trình duyệt này.</p></div><form id="warrantyForm" class="flex" style="align-self:center"><input class="field" name="code" required placeholder="Nhập mã đơn DatDev Mobile"/><button class="btn">Tra cứu ${icon('arrow')}</button></form></div><div id="warrantyResult"></div></div><div class="service-grid mt24">${[['shield','Bảo hành minh bạch','Quy trình hỗ trợ thiết bị rõ ràng'],['edit','Sửa chữa & kỹ thuật','Tạo yêu cầu và hẹn kiểm tra'],['calendar','Đặt lịch trước','Chủ động chọn thời gian phù hợp']].map(([i,t,d])=>`<div class="service-card">${icon(i)}<h3>${t}</h3><p>${d}</p></div>`).join('')}</div><div class="split section-tight"><div class="panel p32"><h3>Đặt lịch hỗ trợ</h3><form id="serviceForm" class="mt24"><div class="form-row"><input class="field" name="name" required placeholder="Họ và tên"/><input class="field" name="phone" pattern="[0-9+ ]{9,15}" required placeholder="Số điện thoại"/></div><div class="form-row"><select name="service"><option>Kiểm tra bảo hành</option><option>Tư vấn sửa chữa</option><option>Hỗ trợ kỹ thuật</option></select><input class="field" type="date" name="date" required min="2026-11-04"/></div><button class="btn full">Gửi yêu cầu demo ${icon('arrow')}</button></form></div><div class="panel p32"><h3>Câu hỏi thường gặp</h3>${faqs([['Tôi tra cứu bảo hành như thế nào?','Dùng mã đơn hàng được tạo trong bản demo. Trên hệ thống thật cần kết nối dữ liệu IMEI và chính sách nhà bán hàng.'],['Bảo hành áp dụng bao lâu?','Thời hạn thực tế phụ thuộc nhà sản xuất và chương trình bán hàng; bản mẫu không cam kết thời hạn.'],['Có được hẹn sửa chữa trước không?','Form mẫu minh họa luồng đặt lịch, chưa kết nối cửa hàng thật.']])}</div></div></div>`}
const stores=[{name:'DatDev Mobile — Showroom Trung tâm',address:'TP. Hồ Chí Minh (địa điểm minh họa)',x:64,y:42},{name:'DatDev Mobile — Showroom phía Tây',address:'TP. Hồ Chí Minh (địa điểm minh họa)',x:36,y:51},{name:'DatDev Mobile — Showroom phía Đông',address:'TP. Hồ Chí Minh (địa điểm minh họa)',x:77,y:63}];
function storesPage(){return `<div class="container">${crumb('Hệ thống cửa hàng')}<div class="section-head"><div><span class="eyebrow">EXPERIENCE IN PERSON</span><h1 style="font-size:50px;margin-top:10px">Đến gần hơn.<br/>Trải nghiệm thật.</h1><p>Giao diện tìm cửa hàng thử nghiệm; không hiển thị địa điểm kinh doanh thật.</p></div></div><div class="store-layout mt24"><div><div class="form-row"><select><option>TP. Hồ Chí Minh</option></select><select><option>Tất cả khu vực</option></select></div>${stores.map((s,i)=>`<div class="store-card"><img src="${asset('showroom.webp')}" alt="Không gian cửa hàng mẫu"/><div><b>${E(s.name)}</b><p class="small muted mt8">${E(s.address)}</p><button class="btn small mt8" data-action="store" data-index="${i}">Xem trên bản đồ</button></div></div>`).join('')}</div><div class="store-map" aria-label="Sơ đồ vị trí minh họa, không phải bản đồ thật">${stores.map((s,i)=>`<button class="map-pin" data-action="store" data-index="${i}" aria-label="${E(s.name)}" style="left:${s.x}%;top:${s.y}%"></button>`).join('')}<div id="storeMapCaption" class="panel p24" style="position:absolute;z-index:3;bottom:20px;left:20px;max-width:330px"><strong>Vị trí minh họa</strong><p class="small muted">Chọn ghim để xem cửa hàng demo. Cần tích hợp bản đồ thực khi triển khai.</p></div></div></div><div class="wide-banner mt24" style="min-height:240px"><div><span class="eyebrow highlight">IN-STORE EXPERIENCE</span><h2 style="font-size:33px">Hơn một nơi mua sắm.</h2><p>Khám phá thiết bị, hỏi đáp và nhận hỗ trợ tại chỗ.</p></div><img src="${asset('showroom.webp')}" alt="Showroom mô phỏng"/></div></div>`}
const baseFaqs=[['Làm sao để tra cứu đơn hàng?','Mở mục Tra cứu đơn hàng, nhập mã DatDev Mobile bạn nhận được khi hoàn tất thanh toán demo.'],['Tôi có thể thay đổi thông tin sau khi đặt không?','Trong bản demo chưa hỗ trợ chỉnh sửa đơn; trang quản trị có thể thay đổi trạng thái. Hệ thống thật cần quy trình xác nhận.'],['Thời gian giao hàng là bao lâu?','Chưa tích hợp đơn vị vận chuyển. Thời gian giao hàng thật cần xác nhận theo khu vực, tồn kho và đơn vị giao nhận.'],['Tôi có thể trả góp không?','Bạn có thể dùng công cụ giả lập để tính kỳ hạn; không có phê duyệt khoản vay hay lãi suất thực.'],['Làm sao để yêu cầu bảo hành?','Mở trang Bảo hành, nhập mã đơn được tạo trong bản demo hoặc điền mẫu liên hệ.']];
function faqs(items){return `<div class="faq">${items.map((x,i)=>`<div class="faq-item ${i===0?'open':''}"><button type="button" data-action="faq">${E(x[0])}${icon('chevron')}</button><div class="answer">${E(x[1])}</div></div>`).join('')}</div>`}
function supportPage(){return `<div class="container">${crumb('Hỗ trợ')}<div class="page-hero" style="min-height:300px"><div style="z-index:1"><span class="eyebrow">DATDEV SUPPORT CENTER</span><h1 class="mt16">Chúng tôi luôn ở đây,<br/>khi bạn cần.</h1><p>Những câu trả lời giúp bạn tiếp tục trải nghiệm mua sắm.</p></div><img src="${asset('hero-warranty.webp')}" alt="Sản phẩm công nghệ"/></div><div class="service-grid mt24">${[['headset','Chat trực tuyến','Tính năng demo, chưa kết nối tổng đài'],['phone','Tư vấn qua điện thoại','Dữ liệu liên hệ chưa được thiết lập'],['mail','Liên hệ email','Sẽ tích hợp hòm thư khi triển khai']].map(([i,t,d])=>`<div class="service-card">${icon(i)}<h3>${t}</h3><p>${d}</p><a href="#/bao-hanh" class="text-link mt16">Tìm hiểu ${icon('arrow')}</a></div>`).join('')}</div><div class="split section"><div class="panel p32"><span class="eyebrow">KNOWLEDGE BASE</span><h2 style="margin:10px 0 25px">Tôi có thể giúp gì?</h2>${faqs(baseFaqs)}</div><div class="panel p32"><span class="eyebrow">SERVICE REQUEST</span><h2 style="margin:10px 0 15px">Gửi yêu cầu hỗ trợ.</h2><p class="muted small">Điền thông tin để thấy cách form hoạt động trong bản demo.</p><form id="supportForm" class="mt24"><div class="form-group"><label class="form-label">Tên của bạn</label><input class="field" name="name" required/></div><div class="form-group"><label class="form-label">Email</label><input type="email" class="field" name="email" required/></div><div class="form-group"><label class="form-label">Vấn đề cần hỗ trợ</label><textarea class="field" name="message" rows="4" required></textarea></div><button class="btn full">Gửi yêu cầu demo ${icon('arrow')}</button></form></div></div></div>`}
function articlesCards(arr){return `<div class="article-grid">${arr.map(p=>`<a href="#/bai-viet/${p.slug}" class="article-card"><img loading="lazy" src="${asset(p.image)}" alt="${E(p.title)}"/><div class="body"><span class="chip ghost">${E(p.tag)}</span><h3>${E(p.title)}</h3><p>${E(p.desc)}</p><span class="text-link mt16">Đọc bài viết ${icon('arrow')}</span></div></a>`).join('')}</div>`}
function magazinePage(){return `<div class="container">${crumb('Cẩm nang công nghệ')}<div class="section-head"><div><span class="eyebrow">DATDEV JOURNAL</span><h1 style="margin-top:13px">Tạp chí công nghệ.<br/>Góc nhìn mới.</h1><p style="margin-top:15px">Câu chuyện và kiến thức giúp lựa chọn thiết bị.</p></div></div><div class="wide-banner mt24" style="min-height:350px"><div><span class="eyebrow highlight">FEATURE STORY</span><h2>Điều gì tạo nên một chiếc điện thoại đáng mua?</h2><a class="btn mt24" href="#/bai-viet/cach-chon-dien-thoai">Đọc câu chuyện ${icon('arrow')}</a></div><img src="${asset('editorial.webp')}" alt="Camera điện thoại"/></div><section class="section"><div class="section-head"><h2>Bài viết mới.</h2></div>${articlesCards(posts)}</section></div>`}
function articlePage(slug){const p=posts.find(x=>x.slug===slug)||posts[0];return `<div class="container">${crumb(p.title,[['Cẩm nang','#/cam-nang']])}<article class="article-body"><span class="chip">${E(p.tag)}</span><h1 style="font-size:clamp(38px,5vw,60px);margin:18px 0">${E(p.title)}</h1><p class="lead">${E(p.desc)} · Cập nhật ${E(p.date)}</p><img src="${asset(p.image)}" alt="${E(p.title)}" style="border-radius:17px;width:100%;max-height:430px;object-fit:cover;margin:24px 0"/><h2>01. Bắt đầu từ nhu cầu thật</h2><p>Điện thoại phục vụ rất nhiều mục đích: liên lạc, chụp ảnh, học tập, giải trí và làm việc. Thay vì chỉ chọn sản phẩm có thông số cao nhất, hãy xác định các công việc bạn dùng thường xuyên.</p><h2>02. Chọn ngân sách phù hợp</h2><p>Thiết lập khoảng giá bạn thấy thoải mái, sau đó so sánh những thiết bị trong cùng phân khúc. Ưu tiên trải nghiệm thực tế và chính sách bán hàng rõ ràng.</p><h2>03. Hiểu sự đánh đổi</h2><p>Camera, thời lượng pin, chất lượng màn hình, hiệu năng và kích thước có thể quan trọng ở những mức độ khác nhau. Không có một sản phẩm phù hợp với tất cả mọi người.</p><div class="panel p32 mt24"><h3>So sánh trước khi quyết định</h3><p class="muted mt8">Đặt các mẫu cạnh nhau để nhìn thấy điểm tương đồng và khác biệt.</p><a href="#/so-sanh" class="btn mt16">Mở công cụ so sánh ${icon('arrow')}</a></div></article><section class="section"><div class="section-head"><h2>Đọc tiếp.</h2></div>${articlesCards(posts.filter(x=>x.slug!==p.slug))}</section></div>`}
const adminNav=[['#/admin','Tổng quan','grid'],['#/admin/don-hang','Đơn hàng','cart'],['#/admin/san-pham','Sản phẩm / CRUD','package'],['#/admin/kho','Kho & tồn hàng','store'],['#/admin/khuyen-mai','Khuyến mãi','tag'],['#/admin/bao-cao','Báo cáo','chart'],['#/','Về cửa hàng','arrow']];
function adminShell(page){return `<div class="admin-shell"><aside class="admin-sidebar"><a href="#/admin" class="logo"><strong>DatDev</strong><span class="slash">/</span><em>MOBILE</em></a><div class="small" style="color:#999;padding:0 16px 20px">ADMIN EXPERIENCE · DEMO</div>${adminNav.map(([href,label,i])=>`<a class="navitem ${path()===href.slice(1)?'active':''}" href="${href}">${icon(i)}<span>${label}</span></a>`).join('')}<div style="margin-top:auto;padding:17px;background:#292b27;border-radius:13px"><span class="chip dark">DATDEV STUDIO</span><p class="small mt16">Dữ liệu quản trị được lưu trong trình duyệt của bạn.</p></div></aside><main class="admin-main"><div class="admin-top"><div><span class="eyebrow">DATDEV MOBILE / CONTROL CENTER</span><p>Quản trị cửa hàng — phiên bản demo</p></div><div class="flex wrap"><span class="chip green">● Local demo</span><a href="#/" class="btn outline small">Xem cửa hàng ${icon('arrow')}</a></div></div>${page}</main></div>`}
function chartSvg(){return `<svg viewBox="0 0 710 230" preserveAspectRatio="none" role="img" aria-label="Biểu đồ doanh thu mẫu trong 30 ngày"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#d8fb5b" stop-opacity=".64"/><stop offset="1" stop-color="#d8fb5b" stop-opacity="0"/></linearGradient></defs>${[30,75,120,165,210].map(y=>`<path d="M0 ${y}H710" stroke="#e7e8e2" stroke-width="1"/>`).join('')}<path d="M0 197L24 190 46 175 68 185 92 160 114 172 136 156 158 149 180 156 202 123 224 138 246 126 268 115 290 126 312 97 334 117 356 104 378 87 400 101 422 81 444 93 466 73 488 82 510 64 532 73 554 45 576 60 598 40 620 52 642 32 664 43 686 18 710 28V230H0Z" fill="url(#fade)"/><polyline points="0,197 24,190 46,175 68,185 92,160 114,172 136,156 158,149 180,156 202,123 224,138 246,126 268,115 290,126 312,97 334,117 356,104 378,87 400,101 422,81 444,93 466,73 488,82 510,64 532,73 554,45 576,60 598,40 620,52 642,32 664,43 686,18 710,28" stroke="#a0c730" stroke-width="3" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
function adminHome(){const sales=orders.reduce((s,o)=>s+o.total,0);return adminShell(`<div class="admin-title-row"><div><h2>Tổng quan kinh doanh</h2><p class="muted">Nhìn nhanh hiệu suất bán hàng của cửa hàng.</p></div><select style="width:160px"><option>30 ngày (demo)</option></select></div><div class="kpis"><div class="kpi" style="background:#181918;color:#fff"><span style="color:var(--lime)">Tổng giá trị đơn demo</span><strong>${money(sales)}</strong><span>Trong trình duyệt hiện tại</span></div><div class="kpi">${icon('package')}<strong>${orders.length}</strong><span>Đơn hàng</span></div><div class="kpi">${icon('grid')}<strong>${products.length}</strong><span>Loại sản phẩm</span></div><div class="kpi">${icon('info')}<strong>${products.filter(x=>x.stock<10).length}</strong><span>Sản phẩm gần hết</span></div></div><div class="admin-two"><section class="admin-card"><div class="flex between"><h3>Doanh thu & đơn hàng</h3><span class="chip ghost">Biểu đồ mẫu</span></div><div class="chartbox">${chartSvg()}</div><p class="small muted">Đường biểu diễn dùng dữ liệu minh họa, không được suy ra từ giao dịch thực.</p></section><section class="admin-card"><h3>Doanh số theo thương hiệu</h3><div style="margin-top:20px">${['Apple','Samsung','Xiaomi','Nothing'].map((brand,i)=>`<div style="margin-bottom:20px"><div class="flex between"><b>${brand}</b><span class="small muted">${[45,27,18,10][i]}%</span></div><div style="height:8px;background:#eee;border-radius:20px;margin-top:8px"><div style="height:100%;width:${[45,27,18,10][i]}%;background:${['#d8fb5b','#a3cd33','#5d7b25','#2b2b2b'][i]};border-radius:20px"></div></div></div>`).join('')}</div><p class="small muted">Cơ cấu minh họa.</p></section></div><div class="admin-two mt16"><section class="admin-card"><div class="section-head"><h3>Đơn hàng gần đây</h3><a class="text-link" href="#/admin/don-hang">Xem tất cả ${icon('arrow')}</a></div>${orders.length?adminOrderTable(orders.slice(0,4)):'<p class="muted mt16">Chưa có đơn hàng demo. Thử đặt hàng từ phía cửa hàng.</p>'}</section><section class="admin-card"><h3>Cảnh báo tồn kho</h3>${products.filter(x=>x.stock<10).map(x=>`<div class="money-row"><span>${E(x.name)}</span><span class="chip red">Còn ${x.stock}</span></div>`).join('')}<a href="#/admin/kho" class="btn small mt16">Quản lý tồn kho ${icon('arrow')}</a></section></div>`)}
function adminProducts(){return adminShell(`<div class="admin-title-row"><div><h2>Danh sách sản phẩm</h2><p class="muted">Quản lý thông tin, giá và tồn kho (localStorage).</p></div><button class="btn" data-action="newProduct">${icon('plus')} Thêm sản phẩm</button></div><div class="kpis"><div class="kpi"><span>Tổng sản phẩm</span><strong>${products.length}</strong></div><div class="kpi"><span>Còn hàng</span><strong>${products.filter(x=>x.stock>0).length}</strong></div><div class="kpi"><span>Hết hàng</span><strong>${products.filter(x=>x.stock===0).length}</strong></div><div class="kpi"><span>Gần hết (&lt; 10)</span><strong>${products.filter(x=>x.stock<10).length}</strong></div></div><div class="admin-card"><div class="flex between wrap mb20"><h3>Sản phẩm đang quản lý</h3><span class="chip ghost">CRUD demo</span></div><div class="admin-table-wrap"><table class="data-table"><thead><tr><th>Sản phẩm</th><th>SKU</th><th>Thương hiệu</th><th>Tồn kho</th><th>Giá bán</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>${products.map(p=>`<tr><td><img src="${asset(p.image)}" alt=""/><span class="admin-table-title">${E(p.name)}</span></td><td>${E(p.id.toUpperCase())}</td><td>${E(p.brand)}</td><td>${p.stock}</td><td><b>${money(p.price)}</b></td><td><span class="chip ${p.stock===0?'red':p.stock<10?'ghost':'green'}">${p.stock===0?'Hết hàng':p.stock<10?'Sắp hết':'Đang bán'}</span></td><td><div class="flex"><button class="icon-button" style="color:#171717" aria-label="Sửa sản phẩm" data-action="editProduct" data-id="${E(p.id)}">${icon('edit')}</button>${!initialProducts.some(x=>x.id===p.id)?`<button class="icon-button" style="color:#a33" aria-label="Xóa sản phẩm" data-action="deleteProduct" data-id="${E(p.id)}">${icon('trash')}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div></div>${productModal()}`)}
function productModal(p){if(!adminModal)return '';const isEdit=typeof adminModal==='string';if(isEdit)p=products.find(x=>x.id===adminModal);return `<div class="modal-cover" id="productModal"><div class="modal"><div class="flex between"><div><span class="eyebrow">DATDEV PRODUCT CMS</span><h2 class="mt8">${isEdit?'Chỉnh sửa':'Thêm'} sản phẩm</h2></div><button class="icon-button" data-action="closeModal" aria-label="Đóng">${icon('close')}</button></div><p class="small muted mt8">Dữ liệu mới được lưu cục bộ; sản phẩm mặc định chỉ chỉnh được giá/tồn kho.</p><form id="productForm" class="mt24"><input type="hidden" name="editId" value="${isEdit?E(p.id):''}"/><div class="form-group"><label class="form-label">Tên sản phẩm *</label><input name="name" class="field" minlength="3" maxlength="80" required value="${isEdit?E(p.name):''}" ${isEdit&&initialProducts.some(x=>x.id===p.id)?'readonly':''}/></div><div class="form-row"><div><label class="form-label">Thương hiệu</label><select name="brand">${['Apple','Samsung','Xiaomi','Nothing','Khác'].map(b=>`<option ${isEdit&&p.brand===b?'selected':''}>${b}</option>`).join('')}</select></div><div><label class="form-label">Dung lượng</label><select name="storage">${['128GB','256GB','512GB','1TB'].map(s=>`<option ${isEdit&&p.storage===s?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="form-row"><div><label class="form-label">Giá bán (VND)</label><input name="price" type="number" min="0" required class="field" value="${isEdit?p.price:''}"/></div><div><label class="form-label">Giá gốc (VND)</label><input name="oldPrice" type="number" min="0" required class="field" value="${isEdit?p.oldPrice:''}"/></div></div><div class="form-row"><div><label class="form-label">Tồn kho</label><input name="stock" type="number" min="0" required class="field" value="${isEdit?p.stock:10}"/></div><div><label class="form-label">Ảnh mẫu</label><select name="image">${initialProducts.map(x=>`<option value="${x.image}" ${isEdit&&p.image===x.image?'selected':''}>${E(x.name)}</option>`).join('')}</select></div></div><div class="form-group"><label class="form-label">Mô tả ngắn</label><textarea class="field" name="desc" rows="3">${isEdit?E(p.desc):''}</textarea></div><button class="btn full" type="submit">${isEdit?'Lưu thay đổi':'Tạo sản phẩm'} ${icon('arrow')}</button></form></div></div>`}
function adminStock(){return adminShell(`<div class="admin-title-row"><div><h2>Tồn kho & điều chuyển</h2><p class="muted">Theo dõi, cập nhật tồn hàng giả lập.</p></div><span class="chip ghost">LOCAL INVENTORY</span></div><div class="kpis"><div class="kpi"><span>Tổng tồn</span><strong>${products.reduce((s,p)=>s+p.stock,0)}</strong></div><div class="kpi"><span>Sắp hết</span><strong>${products.filter(x=>x.stock<10&&x.stock>0).length}</strong></div><div class="kpi"><span>Hết hàng</span><strong>${products.filter(x=>!x.stock).length}</strong></div><div class="kpi"><span>Đang kinh doanh</span><strong>${products.filter(x=>x.stock>0).length}</strong></div></div><div class="admin-two"><section class="admin-card"><h3>Chi tiết tồn kho</h3><div class="admin-table-wrap mt16"><table class="data-table"><thead><tr><th>Sản phẩm</th><th>Thương hiệu</th><th>Tồn hiện tại</th><th>Ngưỡng</th><th>Trạng thái</th></tr></thead><tbody>${products.map(p=>`<tr><td><img src="${asset(p.image)}" alt=""/>${E(p.name)}</td><td>${E(p.brand)}</td><td><b>${p.stock}</b></td><td>10</td><td><span class="chip ${p.stock>=10?'green':'red'}">${p.stock>=10?'Đủ hàng':'Cần bổ sung'}</span></td></tr>`).join('')}</tbody></table></div></section><section class="admin-card"><h3>Điều chỉnh tồn kho</h3><p class="small muted mt8">Không tạo phiếu kho thật. Chỉ cộng/trừ số lượng sản phẩm mẫu.</p><form id="stockForm" class="mt24"><div class="form-group"><label class="form-label">Sản phẩm</label><select name="id">${products.map(p=>`<option value="${p.id}">${E(p.name)} — còn ${p.stock}</option>`).join('')}</select></div><div class="form-group"><label class="form-label">Loại biến động</label><select name="type"><option value="add">Nhập kho (+)</option><option value="subtract">Xuất kho (-)</option></select></div><div class="form-group"><label class="form-label">Số lượng</label><input type="number" min="1" max="10000" value="5" required name="qty" class="field"/></div><div class="form-group"><label class="form-label">Ghi chú</label><textarea class="field" rows="3" name="note" placeholder="Ví dụ: kiểm kê kho"></textarea></div><button class="btn full">Cập nhật kho ${icon('arrow')}</button></form></section></div><div class="panel p24 mt24" style="background:#191a18;color:white"><div class="flex between"><h3>Quy trình vận hành</h3><span class="chip dark">NHẬP KHO → BÁN HÀNG → KIỂM KÊ</span></div></div>`)}
function adminOrderTable(arr){return `<div class="admin-table-wrap"><table class="data-table"><thead><tr><th>Mã đơn</th><th>Khách</th><th>Sản phẩm</th><th>Giá trị</th><th>Trạng thái</th></tr></thead><tbody>${arr.map(o=>`<tr><td><b>${E(o.id)}</b></td><td>${E(o.name)}</td><td>${o.items.length} loại</td><td><b>${money(o.total)}</b></td><td><span class="chip ghost">${E(o.status)}</span></td></tr>`).join('')}</tbody></table></div>`}
function adminOrders(){return adminShell(`<div class="admin-title-row"><div><h2>Quản lý đơn hàng</h2><p class="muted">Duyệt trạng thái đơn hàng được tạo trong demo.</p></div><span class="chip green">${orders.length} đơn</span></div><div class="kpis"><div class="kpi"><span>Đơn hàng</span><strong>${orders.length}</strong></div><div class="kpi"><span>Đã xác nhận</span><strong>${orders.filter(o=>o.status===stages[0]).length}</strong></div><div class="kpi"><span>Đang giao</span><strong>${orders.filter(o=>o.status===stages[2]).length}</strong></div><div class="kpi"><span>Đã giao</span><strong>${orders.filter(o=>o.status===stages[3]).length}</strong></div></div><div class="admin-card"><div class="flex between mb20"><h3>Tất cả đơn hàng</h3><span class="chip ghost">Không kết nối đơn vị vận chuyển</span></div>${orders.length?`<div class="admin-table-wrap"><table class="data-table"><thead><tr><th>Mã đơn</th><th>Khách</th><th>Ngày</th><th>Tổng tiền</th><th>Thanh toán</th><th>Trạng thái</th><th>Cập nhật</th></tr></thead><tbody>${orders.map(o=>`<tr><td><b>${E(o.id)}</b></td><td>${E(o.name)}<br/><span class="muted">${E(o.phone)}</span></td><td>${E(o.date)}</td><td><b>${money(o.total)}</b></td><td>${E(o.payment)}</td><td><span class="chip ghost">${E(o.status)}</span></td><td><select class="admin-status" data-id="${E(o.id)}" style="min-width:170px">${stages.map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h3>Chưa có đơn hàng</h3><p class="muted">Vào website mua thử để tạo đơn hàng demo.</p><a class="btn mt16" href="#/dien-thoai">Tạo đơn mẫu ${icon('arrow')}</a></div>`}</div>`)}
function adminPromos(){return adminShell(`<div class="admin-title-row"><div><h2>Khuyến mãi & Marketing</h2><p class="muted">Không gian cấu hình chương trình ưu đãi.</p></div><span class="chip">MARKETING UI</span></div><div class="kpis"><div class="kpi"><span>Voucher đang hoạt động</span><strong>1</strong></div><div class="kpi"><span>Chiến dịch demo</span><strong>3</strong></div><div class="kpi"><span>Đã dùng trên giỏ</span><strong>${voucher.trim().toUpperCase()==='DATDEV100'?1:0}</strong></div><div class="kpi"><span>Mức giảm voucher</span><strong style="font-size:21px">100.000đ</strong></div></div><div class="admin-two"><section class="admin-card"><h3>Chương trình ưu đãi</h3>${[['Deal công nghệ','Đang hiển thị','#/uu-dai'],['Thu cũ đổi mới','Trang dịch vụ','#/thu-cu-doi-moi'],['Voucher DATDEV100','Giảm 100.000đ trên giỏ','#/gio-hang']].map(x=>`<div class="money-row"><div><b>${x[0]}</b><div class="small muted">${x[1]}</div></div><a class="btn outline small" href="${x[2]}">Xem ${icon('arrow')}</a></div>`).join('')}</section><section class="admin-card"><h3>Thiết lập banner</h3><p class="muted mt16">Module CMS banner, lịch khuyến mãi, coupon, phân khúc khách hàng và tracking chiến dịch sẽ cần backend khi triển khai production.</p><div class="panel-soft p24 mt24"><span class="eyebrow">CAMPAIGN PREVIEW</span><h2 class="mt16">DEAL ĐỈNH.<br/>GIÁ CHẤT.</h2><a href="#/uu-dai" class="btn mt16">Xem trước ${icon('arrow')}</a></div></section></div>`)}
function adminReports(){let values=[22,36,30,47,42,62,70,54,67,77,90,82];return adminShell(`<div class="admin-title-row"><div><h2>Báo cáo & phân tích</h2><p class="muted">Dữ liệu kết hợp đơn mẫu và biểu đồ minh họa.</p></div><button class="btn outline" data-action="csv">${icon('chart')} Xuất CSV đơn hàng</button></div><div class="kpis"><div class="kpi"><span>Giá trị đơn demo</span><strong>${money(orders.reduce((s,o)=>s+o.total,0))}</strong></div><div class="kpi"><span>Số đơn demo</span><strong>${orders.length}</strong></div><div class="kpi"><span>Giá trị TB/đơn</span><strong>${money(orders.length?orders.reduce((s,o)=>s+o.total,0)/orders.length:0)}</strong></div><div class="kpi"><span>Sản phẩm mẫu</span><strong>${products.length}</strong></div></div><div class="admin-two"><section class="admin-card"><h3>Xu hướng doanh thu — dữ liệu minh họa</h3><div class="bar-chart mt24">${values.map(v=>`<span style="height:${v}%" title="Chỉ số minh họa ${v}"></span>`).join('')}</div><div class="flex between small muted mt8"><span>Tháng 1</span><span>Tháng 6</span><span>Tháng 12</span></div></section><section class="admin-card"><h3>Cần bổ sung trước khi triển khai thật</h3><div class="mt24">${['API đơn hàng, hoàn tiền, trạng thái','Thống kê server có kiểm chứng','Theo dõi conversion & attribution','Dữ liệu tồn kho theo chi nhánh','Phân quyền và nhật ký thao tác'].map(x=>`<div class="money-row">${icon('checkcircle')}<span>${x}</span></div>`).join('')}</div></section></div>`)}
function notFound(){return `<div class="container"><div class="empty" style="margin:50px 0"><h1>404.</h1><p class="muted mt16">Trang không tồn tại trong bản demo.</p><a href="#/" class="btn mt16">Về trang chủ ${icon('arrow')}</a></div></div>`}
function render(){const route=path();let output='';let isAdmin=route==='/admin'||route.startsWith('/admin/');if(isAdmin){switch(route){case '/admin':output=adminHome();break;case '/admin/san-pham':output=adminProducts();break;case '/admin/kho':output=adminStock();break;case '/admin/don-hang':output=adminOrders();break;case '/admin/khuyen-mai':output=adminPromos();break;case '/admin/bao-cao':output=adminReports();break;default:output=adminHome();}$('#app').innerHTML=output;document.title='DatDev Mobile | Admin demo';return}
switch(true){case route==='/':output=home();break;case route==='/dien-thoai':output=listPage();break;case route==='/phu-kien':output=listPage(true);break;case route==='/tim-kiem':output=searchPage();break;case route.startsWith('/san-pham/'):output=productPage(decodeURIComponent(route.split('/')[2]));break;case route==='/so-sanh':output=comparePage();break;case route==='/uu-dai':output=offersPage();break;case route==='/thu-cu-doi-moi':output=tradeInPage();break;case route==='/tra-gop':output=installmentPage();break;case route==='/gio-hang':output=cartPage();break;case route==='/thanh-toan':output=checkoutPage();break;case route==='/dat-hang-thanh-cong':output=successPage();break;case route==='/tra-cuu':output=trackPage();break;case route==='/dang-nhap':output=loginPage();break;case route==='/tai-khoan':output=accountPage();break;case route==='/don-hang':output=ordersPage();break;case route==='/yeu-thich':output=wishlistPage();break;case route==='/bao-hanh':output=warrantyPage();break;case route==='/cua-hang':output=storesPage();break;case route==='/ho-tro':output=supportPage();break;case route==='/cam-nang':output=magazinePage();break;case route.startsWith('/bai-viet/'):output=articlePage(route.split('/')[2]);break;default:output=notFound()}
$('#app').innerHTML=header()+`<main id="mainContent">${output}</main>`+footer();document.title='DatDev Mobile | '+(route==='/'?'Công nghệ. Đúng chất bạn.':route.slice(1).replaceAll('-',' '));}
function persistCatalog(){const originalIds=new Set(initialProducts.map(x=>x.id));storage.write('newproducts',products.filter(x=>!originalIds.has(x.id)));storage.write('catalogEdits',Object.fromEntries(products.filter(x=>originalIds.has(x.id)).map(p=>[p.id,{price:p.price,oldPrice:p.oldPrice,stock:p.stock}])))}
Object.entries(storage.read('catalogEdits',{})).forEach(([id,changes])=>{const p=products.find(x=>x.id===id);if(p){for(const field of ['price','oldPrice','stock'])if(Number.isFinite(changes[field]))p[field]=changes[field]}});
const rerender=()=>{render()};
document.addEventListener('click',e=>{
const el=e.target.closest('[data-action]');if(!el)return;
const act=el.dataset.action,id=el.dataset.id;
if(act==='menu'){$('#mobileNav')?.classList.toggle('open');return}
if(act==='faq'){el.parentElement.classList.toggle('open');return}
if(act==='wish'){wish=wish.includes(id)?wish.filter(x=>x!==id):[...wish,id];save();rerender();notice(wish.includes(id)?'Đã lưu vào yêu thích':'Đã bỏ khỏi yêu thích');return}
if(act==='add'||act==='buy'){const p=products.find(x=>x.id===id);if(!p||p.stock<=0)return notice('Sản phẩm hiện không có tồn kho mẫu');const item=cart.find(x=>x.id===id);if(item)item.qty=Math.min(item.qty+1,p.stock);else cart.push({id,qty:1,size:selectedSize||p.storage});save();if(act==='buy')go('/gio-hang');else{rerender();notice('Đã thêm '+p.name+' vào giỏ hàng')}return}
if(act==='compare'){if(compared.includes(id)){compared=compared.filter(x=>x!==id);notice('Đã bỏ khỏi danh sách so sánh')}else if(compared.length>=3){return notice('Chỉ so sánh tối đa 3 sản phẩm')}else{compared.push(id);notice('Đã thêm vào so sánh — mở trang So sánh để xem')}save();rerender();return}
if(act==='qty'){const p=products.find(x=>x.id===id),item=cart.find(x=>x.id===id);if(item){item.qty=Math.max(0,Math.min((p?.stock||99),item.qty+Number(el.dataset.amount)));if(item.qty===0)cart=cart.filter(x=>x.id!==id);save();rerender()}return}
if(act==='remove'){cart=cart.filter(x=>x.id!==id);save();rerender();notice('Đã xóa sản phẩm');return}
if(act==='clearCart'){cart=[];save();rerender();return}
if(act==='voucher'){voucher=$('#voucherInput')?.value.trim()||'';save();rerender();notice(voucher.toUpperCase()==='DATDEV100'?'Áp dụng giảm 100.000đ (demo)':'Mã không hợp lệ; thử DATDEV100');return}
if(act==='resetFilters'){brandFilter='Tất cả';maxPrice=50000000;sortFilter='featured';go('/dien-thoai');return}
if(act==='color'){selectedColor=Number(el.dataset.index);document.querySelectorAll('.swatch').forEach((s,i)=>s.classList.toggle('selected',i===selectedColor));return}
if(act==='size'){selectedSize=el.dataset.value;document.querySelectorAll('.option-btn').forEach(b=>b.classList.toggle('active',b.dataset.value===selectedSize));return}
if(act==='estimateTrade'){const condition=$('#tradeCondition')?.value;const price=condition==='good'?18500000:condition==='okay'?14900000:9900000;$('#tradeResult').innerHTML=`<p>Giá thu cũ ước tính (dữ liệu minh họa)</p><strong>${money(price)}</strong><p class="small mt8">Ước tính phi thương mại; cần kiểm tra máy trực tiếp mới có giá thật.</p>`;notice('Đã tính thử giá thu cũ');return}
if(act==='store'){const store=stores[Number(el.dataset.index)];if(store){$('#storeMapCaption').innerHTML=`<strong>${E(store.name)}</strong><p class="small muted">${E(store.address)}</p><p class="small">Địa điểm minh họa — không thể chỉ đường</p>`}return}
if(act==='reorder'){const order=orders.find(x=>x.id===id);if(order){for(const x of order.items){const prod=products.find(p=>p.id===x.id);if(prod&&prod.stock>0){const existing=cart.find(y=>y.id===x.id);if(existing)existing.qty=Math.min(existing.qty+x.qty,prod.stock);else cart.push({id:x.id,qty:Math.min(x.qty,prod.stock),size:x.storage})}}save();go('/gio-hang');notice('Đã thêm sản phẩm còn hàng vào giỏ')}return}
if(act==='newProduct'){adminModal=true;rerender();return}
if(act==='editProduct'){adminModal=id;rerender();return}
if(act==='closeModal'){adminModal=false;rerender();return}
if(act==='deleteProduct'){if(!confirm('Xóa sản phẩm demo này?'))return;products=products.filter(p=>p.id!==id);persistCatalog();rerender();notice('Đã xóa sản phẩm mẫu');return}
if(act==='csv'){const rows=[['Ma don','Khach hang','Ngay tao','Tong VND','Trang thai'],...orders.map(o=>[o.id,o.name,o.date,o.total,o.status])];const val=rows.map(r=>r.map(c=>'"'+String(c).replaceAll('"','""')+'"').join(',')).join('\r\n');const blob=new Blob(['\ufeff'+val],{type:'text/csv;charset=utf-8'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download='datdev-mobile-orders-demo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);notice('Đã xuất CSV đơn hàng demo');return}
});
document.addEventListener('submit',e=>{
const f=e.target;if(!f.id)return;e.preventDefault();
const d=new FormData(f),get=k=>String(d.get(k)||'').trim();
if(f.id==='searchForm'){go('/tim-kiem?q='+encodeURIComponent(get('q')));return}
if(f.id==='trackForm'){go('/tra-cuu?id='+encodeURIComponent(get('orderId')));return}
if(f.id==='loginForm'){if(get('otp')!=='123456')return notice('Mã OTP demo là 123456');storage.write('login',get('identity'));go('/tai-khoan');notice('Đăng nhập demo thành công');return}
if(f.id==='supportForm'||f.id==='serviceForm'){f.reset();notice('Đã ghi nhận yêu cầu mô phỏng — chưa gửi đến nhân viên');return}
if(f.id==='warrantyForm'){const order=orders.find(o=>o.id===get('code'));const box=$('#warrantyResult');box.innerHTML=order?`<div class="range-result mt24"><b>Tìm thấy đơn demo ${E(order.id)}</b><p class="small">Trạng thái: ${E(order.status)} · ${E(order.date)}</p><p class="small">Thời hạn bảo hành thực tế không thể tra cứu từ bản demo.</p></div>`:`<p class="chip red mt16">Không tìm thấy mã đơn trong trình duyệt này</p>`;return}
if(f.id==='checkoutForm'){
  const t=summaryTotals();if(!t.items.length)return notice('Giỏ hàng trống');
  const date=new Date();const id='DDM-'+date.getFullYear()+String(date.getMonth()+1).padStart(2,'0')+String(date.getDate()).padStart(2,'0')+'-'+String(Math.floor(1000+Math.random()*9000));
  const order={id,name:get('buyerName'),phone:get('buyerPhone'),email:get('buyerEmail'),address:get('address'),payment:get('payment'),delivery:get('delivery'),date:date.toLocaleString('vi-VN'),items:t.items.map(({item,p})=>({id:p.id,name:p.name,qty:item.qty,storage:item.size,price:p.price})),total:t.total,status:stages[0]};
  orders.unshift(order);cart=[];voucher='';save();go('/dat-hang-thanh-cong');notice('Đã tạo đơn demo — không phát sinh giao dịch');return}
if(f.id==='stockForm'){
  const p=products.find(x=>x.id===get('id'));const qty=Number(get('qty'));if(!p||!Number.isSafeInteger(qty)||qty<=0)return notice('Số lượng không hợp lệ');if(get('type')==='subtract'&&qty>p.stock)return notice('Không đủ số lượng tồn kho');p.stock+=(get('type')==='add'?qty:-qty);persistCatalog();rerender();notice('Đã cập nhật tồn kho cục bộ');return}
if(f.id==='productForm'){
  const editId=get('editId'),name=get('name'),price=Number(get('price')),oldPrice=Number(get('oldPrice')),stock=Number(get('stock'));
  if(!name||!Number.isFinite(price)||!Number.isFinite(oldPrice)||!Number.isSafeInteger(stock)||price<0||oldPrice<price||stock<0)return notice('Kiểm tra giá, giá gốc và tồn kho');
  const base={name,brand:get('brand'),storage:get('storage'),price,oldPrice,stock,image:get('image'),desc:get('desc')||'Thiết bị công nghệ cho bạn.',color:'Tùy chọn',rate:4.5,reviews:0,badge:'Mới cập nhật',specs:{'Màn hình':'Chưa cập nhật','Chip':'Chưa cập nhật','Camera':'Chưa cập nhật','Pin':'Chưa cập nhật'}};
  if(editId){const existing=products.find(x=>x.id===editId);if(!existing)return notice('Không tìm thấy sản phẩm');const isOriginal=initialProducts.some(x=>x.id===editId);if(isOriginal){existing.price=price;existing.oldPrice=oldPrice;existing.stock=stock}else Object.assign(existing,base)}
  else{const id='datdev-'+Date.now().toString(36);products.push({id,...base})}
  persistCatalog();adminModal=false;rerender();notice('Đã lưu sản phẩm demo');return}
});
document.addEventListener('change',e=>{
const t=e.target;if(t.name==='brand'){brandFilter=t.value;go('/dien-thoai');return}
if(t.id==='sortProducts'){sortFilter=t.value;rerender();return}
if(t.id==='installProduct'||t.id==='installMonths')updateInstallment();
if(t.classList.contains('compare-select')){const idx=Number(t.dataset.index);if(compared.length===0)compared=products.slice(0,3).map(x=>x.id);if(t.value)compared[idx]=t.value;else compared.splice(idx,1);compared=[...new Set(compared)].slice(0,3);save();rerender();return}
if(t.classList.contains('admin-status')){const o=orders.find(x=>x.id===t.dataset.id);if(o&&stages.includes(t.value)){o.status=t.value;save();rerender();notice('Đã cập nhật trạng thái đơn demo')}return}
});
function updateInstallment(){const prod=products.find(x=>x.id===$('#installProduct')?.value)||products[0];const el=$('#depositInput');if(!el)return;el.max=prod.price;el.value=Math.min(Number(el.value),prod.price);const deposit=Number(el.value),months=Number($('#installMonths')?.value)||6;$('#depositLabel').textContent=money(deposit);$('#installMonthly').textContent=money(Math.ceil((prod.price-deposit)/months))}
document.addEventListener('input',e=>{if(e.target.id==='maxPrice'){maxPrice=Number(e.target.value);$('#rangeLabel').textContent=money(maxPrice);clearTimeout(window.filterTimer);window.filterTimer=setTimeout(rerender,250)}if(e.target.id==='depositInput')updateInstallment()});
window.addEventListener('hashchange',()=>{adminModal=false;render();window.scrollTo({top:0,behavior:'instant'})});
render();
})();
